const icons={box:'<path d="m12 3 9 5v9l-9 5-9-5V8l9-5Z"/><path d="m3 8 9 5 9-5M12 13v9M7.5 5.5l9 5"/>',home:'<path d="m3 10 9-7 9 7v10H7v-7h5v7"/>',receipt:'<path d="M5 3h14v19l-3-2-4 2-4-2-3 2V3Z"/><path d="M8 7h8M8 11h8M8 15h4"/>',return:'<path d="M8 7h8a6 6 0 0 1 0 12H8M8 7l4-4M8 7l4 4"/>',plan:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 11h18M8 15h2M14 15h2"/>',settings:'<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"/><path d="m10 3 1-1h2l1 1 .5 2 2 .8 2-.5 1 1 1 2-1.5 1.5V13l1.5 1.5-1 2-1 1-2-.5-2 .8-.5 2-1 1h-2l-1-1-.5-2-2-.8-2 .5-1-1-1-2L5 13v-2.2L3.5 9.3l1-2 1-1 2 .5 2-.8L10 3Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14M14 7l5 5-5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m14 6-6 6 6 6"/>',bell:'<path d="M6 9a6 6 0 0 1 12 0v7l2 2H4l2-2V9ZM10 21h4"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v.1"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',money:'<circle cx="12" cy="12" r="9"/><path d="M15 8h-5a2 2 0 0 0 0 4h4a2 2 0 0 1 0 4H9M12 6v12"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 5-5 4 4 4-6 5 7"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',edit:'<path d="m16 3 5 5-12 12-6 1 1-6L16 3Z"/><path d="m13 6 5 5"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',upload:'<path d="M12 16V3M7 8l5-5 5 5M4 16v5h16v-5"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',external:'<path d="M14 3h7v7M21 3 11 13M10 5H3v16h16v-7"/>',location:'<path d="M19 10c0 6-7 12-7 12S5 16 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',headphones:'<path d="M4 14v-3a8 8 0 0 1 16 0v3"/><rect x="3" y="12" width="4" height="9" rx="2"/><rect x="17" y="12" width="4" height="9" rx="2"/>',shirt:'<path d="m8 3-6 4 3 5 3-1v10h8V11l3 1 3-5-6-4c0 4-8 4-8 0Z"/>',phone:'<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M10 5h4M11 19h2"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Z"/><path d="m8 12 3 3 5-6"/>',file:'<path d="M5 2h9l5 5v15H5V2ZM14 2v5h5M8 12h8M8 16h6"/>',merge:'<path d="M5 3v4c0 4 7 4 7 8v6M19 3v4c0 4-7 4-7 8M8 17l4 4 4-4"/>',bookmark:'<path d="M6 3h12v19l-6-4-6 4V3Z"/>',camera:'<path d="M3 7h4l2-3h6l2 3h4v14H3V7Z"/><circle cx="12" cy="13" r="4"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.box}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brand=()=>`<a class="brand" href="#today">${icon('box')}<span>Return Pilot</span></a>`;
const button=(label,route,kind='',i='arrow')=>`<a class="btn ${kind}" href="#${route}">${esc(label)}${i?icon(i):''}</a>`;
const pill=(s,kind='')=>`<span class="pill ${kind}">${esc(s)}</span>`;
let state={name:'Alex',email:'alex@example.com',timezone:'America/New_York',notify:true,lead:[7,3,1],channels:{email:true,app:true},taskState:1,history:[],decision:'return',draft:null,tasksAdded:[],planSaved:false};
try{const saved=JSON.parse(localStorage.getItem('return-pilot-reference-v1')||'null');if(saved)state={...state,...saved}}catch{}
function persist(){try{localStorage.setItem('return-pilot-reference-v1',JSON.stringify(state))}catch{}}
const labels={today:'Today',purchases:'Purchases',tasks:'Returns',detail:'Returns',tracking:'Returns',plan:'Return plan',settings:'Settings',add:'Purchases',upload:'Purchases',manual:'Purchases',review:'Purchases',duplicate:'Purchases',policy:'Purchases'};
function shell(route,body){const active=labels[route]||'Today';return `<aside class="sidebar">${brand()}<div class="eyebrow">Your workspace</div><nav class="nav">${[['today','Home','home'],['purchases','Purchases','receipt'],['tasks','Returns','return'],['plan','Return plan','plan'],['settings','Settings','settings']].map(([r,l,i])=>`<a href="#${r}" class="${labels[r]===active?'active':''}" ${labels[r]===active?'aria-current="page"':''}>${icon(i)}<span>${l}</span>${r==='tasks'?'<span class="counter">'+allTasks().filter(x=>itemStage(x)<4).length+'</span>':''}</a>`).join('')}</nav><div class="sidebar-foot"><div class="help-note">A little less to remember.<br>A clear next step for every return.</div><a class="profile" href="#settings"><span class="avatar">${esc(state.name[0]||'A')}</span><span><span class="small strong">${esc(state.name)}</span><br><small class="muted">Personal workspace</small></span><span class="more">···</span></a></div></aside><main class="main"><header class="toolbar"><div class="crumb"><span>Workspace</span><span>/</span><span>${active==='Today'?'Home':active}</span></div><div class="toolbar-right"><span class="demo">Demo workspace</span><button class="icon-button" data-action="reminders" aria-label="Reminder settings">${icon('bell')}</button><a class="avatar" href="#settings" aria-label="Account settings">${esc(state.name[0]||'A')}</a></div></header><div class="content">${body}<div class="footer-note">Return Pilot · All orders, policies, and locations shown are sample data.</div></div></main>`}
const heading=(title,sub,action='',over='')=>`<div class="page-heading"><div>${over?`<div class="eyebrow">${over}</div>`:''}<h1>${title}</h1><p>${sub}</p></div>${action}</div>`;
function today(){return heading('Today','A clear plan for every return.',button('Add purchase','add','','plus'),'Your return workspace')+`<div class="metric-row"><div class="metric"><div class="metric-label">${icon('clock')}Needs attention</div><div class="metric-value">2 <span class="unit">items</span></div><div class="metric-note">One deadline coming up</div></div><div class="metric"><div class="metric-label">${icon('money')}Potential refund</div><div class="metric-value">$128<span class="unit">.99</span></div><div class="metric-note">Across 3 planned returns</div></div><div class="metric"><div class="metric-label">${icon('return')}Awaiting refund</div><div class="metric-value">$49<span class="unit">.99</span></div><div class="metric-note">One return in progress</div></div></div><div class="columns"><section class="panel"><div class="section-title"><div><h2>Your next steps</h2><p>Small actions. Money back on track.</p></div>${pill('2 priorities')}</div><div class="task-row"><div class="date-tile urgent"><small>OCT</small>15</div><div class="task-copy"><h3>Wireless Headphones</h3><p>Sample retailer · Order #1042</p><div class="action-note urgent">Start your return by October 15</div></div><div class="task-action"><span class="price">$59.99</span><a class="row-arrow" href="#detail" data-item="headphones" aria-label="View headphones return">${icon('arrow')}</a></div></div><div class="task-row"><div class="iconbox">${icon('receipt')}</div><div class="task-copy"><h3>Everyday Hoodie</h3><p>Sample retailer · Order #1028</p><div class="action-note">Confirm delivery date to check the window</div></div><div class="task-action"><span class="price">$49.99</span><button class="row-arrow" data-action="review-hoodie" aria-label="Review hoodie purchase">${icon('arrow')}</button></div></div><div class="divider"></div><a class="link" href="#tasks">View all return tasks ${icon('arrow')}</a></section><section class="plan-feature"><div class="eyebrow">A little planning goes a long way</div><div class="plan-date"><div><strong>One trip. Three returns.</strong><small>Wednesday, October 14 · 2–3 PM</small></div><div class="iconbox">${icon('plan')}</div></div><div class="mini-route"><div class="route-item"><span class="route-dot"></span><div><strong>Prepare your packages</strong><small>Headphones, hoodie, and phone case</small></div></div><div class="route-item"><span class="route-dot"></span><div><strong>Drop off at two eligible locations</strong><small>Keep each return in its own package</small></div></div></div><div class="plan-footer"><a class="link" href="#plan">Open your plan ${icon('arrow')}</a><small>3 items · 2 stops</small></div></section></div><section class="panel refund-panel"><div class="panel-heading"><h2>On its way back to you</h2><a class="link" href="#tracking" data-item="hoodie">View progress ${icon('arrow')}</a></div><table class="refund-table"><thead><tr><th>ITEM</th><th>LAST UPDATE</th><th>STATUS</th><th>ESTIMATED REFUND</th></tr></thead><tbody><tr><td>Everyday Hoodie<small>Sample retailer · #1028</small></td><td>${(state.stages?.hoodie??1)>=2?'Dropped off · Oct 13':'Return requested · Oct 12'}</td><td>${pill((state.stages?.hoodie??1)>=4?'Refund received':(state.stages?.hoodie??1)>=2?'Refund pending':'Ready to drop off')}</td><td>$49.99</td></tr></tbody></table><div class="inline-note">${icon('info')}Updates are marked by you. Refund amounts are subject to retailer approval.</div></section>`}
const sampleOrders=[
  {id:'headphones',name:'Wireless Headphones',retailer:'Sample retailer A',order:'RP-1042',price:59.99,purchase:'2026-09-15',delivery:'2026-09-15',deadline:'2026-10-15',category:'Electronics',icon:'headphones',stage:0},
  {id:'hoodie',name:'Everyday Hoodie',retailer:'Sample retailer B',order:'RP-1028',price:49.99,purchase:'2026-09-20',delivery:'',deadline:'2026-10-23',category:'Apparel',icon:'shirt',stage:1},
  {id:'case',name:'Phone Case',retailer:'Sample retailer A',order:'RP-1042',price:19.01,purchase:'2026-09-15',delivery:'2026-09-15',deadline:'2026-10-15',category:'Accessories',icon:'phone',stage:0}
];
const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(v||0));
const date=v=>{if(!v)return 'Not confirmed';const d=new Date(v+'T12:00:00');return Number.isNaN(d.valueOf())?'Not confirmed':d.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})};
const allPurchases=()=>[...sampleOrders,...state.tasksAdded].filter(x=>!(state.hiddenItemIds||[]).includes(x.id)).map(x=>({...x,...(state.purchaseOverrides?.[x.id]||{})}));
const allTasks=()=>allPurchases().filter(x=>!x.decision||x.decision==='return');
const focusItem=()=>allTasks().find(x=>x.id===state.selectedItem)||sampleOrders[0];
const itemStage=item=>state.stages?.[item.id]??item.stage??0;
const stageNames=['Return not started','Ready to drop off','Refund pending','Retailer received','Refund received'];
const notice=(s,kind='')=>`<div class="notice ${kind}">${icon('info')}<div>${s}</div></div>`;
const back=(r,s)=>`<a class="back" href="#${r}">${icon('back')}${s}</a>`;
const steps=n=>`<div class="stepper">${['Add purchase','Review details','Policy match'].map((s,i)=>`${i?'<div class="step-line"></div>':''}<span class="${i===n?'current':''}"><i>${i<n?'✓':i+1}</i>${s}</span>`).join('')}</div>`;
const field=(label,name,value='',type='text',attrs='')=>`<label class="field">${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const draft=()=>state.draft||{retailer:'Sample retailer A',name:'Wireless Headphones',price:59.99,purchase:'2026-09-15',delivery:'2026-09-15',order:'RP-1042',category:'Electronics',source:'Sample receipt'};
let purchaseQuery='',taskFilter='active',fileURL=null,fileName='',selectedFile=null;
function login(){return `<div class="auth"><section class="auth-story">${brand()}<div class="auth-copy"><div class="eyebrow" style="margin-bottom:25px">Returns, without the mental load</div><h1>A clear next step.<br>For every return.</h1><p>Keep the receipts. Know the deadlines. Follow the money back.</p><div class="auth-steps"><span>${icon('receipt')}Add a purchase</span><span>${icon('plan')}Make a plan</span><span>${icon('money')}Follow the refund</span></div></div><div class="small muted">Return Pilot · Desktop design prototype</div></section><section class="auth-body"><div class="auth-form">${brand()}<h2>Welcome to Return Pilot</h2><p>Manage returns before the deadline.</p><form id="login-form">${field('Email address','email',state.email,'email','required autocomplete="email"')}<button class="btn full" type="submit" style="margin-top:17px">Continue with email ${icon('arrow')}</button></form><div class="or">or</div><button class="btn secondary full" data-action="google">G &nbsp; Continue with Google</button><p class="auth-footer">This is an interactive demo. Sign-in providers are not connected.</p><a class="btn ghost full" href="#today">Explore the workspace ${icon('arrow')}</a></div></section></div>`}
function setup(){return heading('Make it yours.','A few details to set up your return workspace.')+`<div class="columns equal"><form class="panel" id="setup-form"><div class="panel-heading"><h2>Account setup</h2>${pill('Step 1 of 2')}</div><div class="form-grid">${field('Name','name',state.name,'text','required maxlength="60"')}${field('Email','email',state.email,'email','required')}<label class="field full">Time zone<select name="timezone"><option value="America/New_York" ${state.timezone==='America/New_York'?'selected':''}>Eastern Time — America/New_York</option><option value="America/Los_Angeles" ${state.timezone==='America/Los_Angeles'?'selected':''}>Pacific Time — America/Los_Angeles</option><option value="Europe/London" ${state.timezone==='Europe/London'?'selected':''}>London — Europe/London</option></select></label></div><div class="divider"></div><div class="settings-row"><div><h3>Reminder preferences</h3><p class="small muted">Choose when and how to be reminded.</p></div><a class="link" href="#settings">Customize ${icon('chevron')}</a></div><div class="divider"></div><h3 style="margin-bottom:10px">Your forwarding address</h3><div class="code-box"><span>alex@inbox.returnpilot.example</span><button type="button" class="icon-button" data-action="copy" aria-label="Copy example forwarding address">${icon('copy')}</button></div><p class="file-note">Example only. This address cannot receive email yet.</p><div class="form-actions"><button class="btn" type="submit">Continue ${icon('arrow')}</button></div></form><section class="panel"><h2>Your workspace, your pace.</h2><div class="walkthrough"><span class="badge-number">1</span><div>Start with your receipts<small>Upload a screenshot, PDF, or enter details yourself.</small></div></div><div class="walkthrough"><span class="badge-number">2</span><div>Confirm the important details<small>You stay in control of dates, items, and amounts.</small></div></div><div class="walkthrough"><span class="badge-number">3</span><div>Plan the next step<small>Turn purchases into a manageable return list.</small></div></div><div class="divider"></div>${notice('Your profile and demo changes stay in this browser.')}</section></div>`}
function add(){return heading('Add a purchase','Start with what you already have. We’ll help organize the rest.')+`<div class="columns"><section class="panel"><div class="panel-heading"><h2>How would you like to add it?</h2>${pill('Four ways in')}</div><div class="option-grid">${[['image','Upload image','Receipt photo or order screenshot','upload'],['file','Upload PDF','Receipt or order confirmation','upload'],['mail','Forward email','Use your dedicated forwarding inbox','email'],['edit','Manual entry','Fill in the purchase details yourself','manual']].map(([i,t,d,r])=>r==='email'?`<button class="option" data-action="email"><span class="iconbox">${icon(i)}</span><span><h3>${t}</h3><p>${d}</p></span>${icon('chevron','chevron')}</button>`:`<a class="option" href="#${r}"><span class="iconbox">${icon(i)}</span><span><h3>${t}</h3><p>${d}</p></span>${icon('chevron','chevron')}</a>`).join('')}</div><div class="divider"></div><div class="inline-note">${icon('shield')}You can edit every extracted field before saving a task.</div></section><section class="panel"><h2>From receipt to return</h2><div class="walkthrough"><span class="badge-number">1</span><div>Add your purchase<small>Keep the original receipt as evidence.</small></div></div><div class="walkthrough"><span class="badge-number">2</span><div>Review & match<small>Confirm the details and check for duplicates.</small></div></div><div class="walkthrough"><span class="badge-number">3</span><div>Decide what to do<small>Keep, return, or come back to it later.</small></div></div></section></div>`}
function upload(){return back('add','Add purchase')+heading('Upload a receipt','Bring a photo, screenshot, or PDF. Review the details before saving.')+steps(0)+`<div class="columns"><section class="panel"><div class="panel-heading"><h2>Purchase evidence</h2>${pill(fileName?'File selected':'JPG · PNG · PDF')}</div><div class="upload-zone" id="drop-zone">${fileURL?`<img src="${fileURL}" alt="Selected receipt preview" style="max-width:100%;max-height:170px;object-fit:contain">`:icon(fileName?'file':'image')}<h3>${fileName?esc(fileName):'Drop a receipt here'}</h3><p>${fileName?'Your file is ready to preview.':'A clear image makes the details easier to review.'}</p><div class="upload-actions"><label class="btn secondary" for="receipt-file">${icon('upload')} Choose a file</label><button class="btn" data-action="sample">Try a sample receipt ${icon('arrow')}</button></div><input type="file" id="receipt-file" hidden accept="image/jpeg,image/png,application/pdf"></div><p class="file-note">Accepted formats: JPG, PNG, PDF · Maximum 10 MB</p><div class="divider"></div>${notice('File preview works locally. OCR is not connected; use the sample or enter details manually.')}<div class="form-actions">${button('Enter details','manual','secondary',null)}${fileName?button('Review file details','review') :''}</div></section><div class="stack"><section class="panel"><h2>Or forward an email</h2><p class="small muted" style="margin:14px 0">Forward the order confirmation to your personal inbox.</p><div class="code-box"><span>alex@inbox.returnpilot.example</span><button class="icon-button" data-action="copy" aria-label="Copy example forwarding address">${icon('copy')}</button></div><p class="file-note">Demo address. Email receiving is not connected.</p></section><section class="panel"><h3>A good receipt includes</h3><div class="checklist" style="margin-top:18px">${['Retailer and order number','Item names and prices','Purchase or delivery date'].map(x=>`<div class="check-row">${icon('check')}<span>${x}</span></div>`).join('')}</div></section></div></div>`}
function purchaseForm(d,mode){return `<form id="${mode}-form" class="panel"><div class="panel-heading"><h2>${mode==='manual'?'Purchase details':'Confirm the details'}</h2>${pill(mode==='manual'?'Editable draft':'Review required')}</div><div class="form-grid">${field('Retailer','retailer',d.retailer,'text','required maxlength="100"')}${field('Item name','name',d.name,'text','required maxlength="150"')}${field('Quantity','quantity',d.quantity||1,'number','required min="1" max="99" step="1"')}${field('Price per item ($)','price',d.price,'number','required min="0.01" step="0.01" max="999999"')}${field('Purchase date','purchase',d.purchase,'date','required max="2026-10-13"')}${field('Delivery date','delivery',d.delivery,'date','max="2026-10-13"')}${field('Order number (optional)','order',d.order,'text','maxlength="100"')}<label class="field">Category<select name="category">${['Electronics','Apparel','Accessories','Home','Other'].map(s=>`<option ${d.category===s?'selected':''}>${s}</option>`).join('')}</select></label></div><div class="divider"></div>${notice('A missing delivery date can change the deadline. You can save a draft and fill it in later.')}<div class="form-actions"><a class="link" href="#${mode==='manual'?'add':'upload'}">Cancel</a><button class="btn" type="submit">${mode==='manual'?'Create draft':'Confirm purchase'} ${icon('arrow')}</button></div></form>`}
function manual(){const d=state.draft||{retailer:'',name:'',price:'',purchase:'',delivery:'',order:'',category:'Electronics'};return back('add','Add purchase')+heading('Enter purchase details','A few details are enough to get started.')+steps(0)+`<div class="columns">${purchaseForm(d,'manual')}<section class="panel"><h2>What matters most</h2><div class="walkthrough"><span class="badge-number">1</span><div>The item and retailer<small>Choose the exact item you’re considering returning.</small></div></div><div class="walkthrough"><span class="badge-number">2</span><div>The dates<small>Some policies use delivery date rather than purchase date.</small></div></div><div class="walkthrough"><span class="badge-number">3</span><div>The amount paid<small>Any fees or deductions depend on the retailer.</small></div></div></section></div>`}
function receipt(d){return `<div class="receipt"><div class="receipt-brand">RETURN PILOT</div><div class="receipt-sub">SAMPLE ORDER CONFIRMATION</div><div class="receipt-separator"></div><div class="receipt-line"><span>Retailer</span><b>${esc(d.retailer)}</b></div><div class="receipt-line"><span>Order</span><b>${esc(d.order||'—')}</b></div><div class="receipt-line"><span>Purchased</span><b>${date(d.purchase)}</b></div><div class="receipt-separator"></div><div class="receipt-line"><span>${esc(d.name)}</span><b>${money(d.price)}</b></div><div class="receipt-line"><span>Quantity</span><b>${d.quantity||1}</b></div><div class="receipt-separator"></div><div class="receipt-line"><span>TOTAL</span><b>${money(d.price*(d.quantity||1))}</b></div><div class="receipt-foot">For prototype demonstration only.</div></div>`}
function review(){const d=draft();return back('upload','Purchase evidence')+heading('Review your purchase','You’re in control. Check the extracted details before going further.')+steps(1)+`<div class="columns equal"><section class="panel"><div class="panel-heading"><h2>Original evidence</h2>${pill(d.source||'Sample receipt')}</div><div class="receipt-preview">${fileURL?`<img src="${fileURL}" alt="Your selected purchase evidence">`:receipt(d)}</div><div class="inline-note">${icon('info')}${fileURL?'File preview only. Fill the fields from your receipt.':'A sample receipt is shown for this demo.'}</div></section>${purchaseForm(d,'review')}</div>`}
function duplicate(){const d=draft();return back('review','Review purchase')+heading('This order looks familiar.','Check the records before creating another purchase.')+steps(1)+`<div class="columns"><section class="panel"><div class="panel-heading"><h2>Possible duplicate</h2>${pill('Order number match','urgent')}</div>${notice('A sample record has the same order number. Compare the details and choose what to keep.','warn')}<div class="option-grid" style="margin-top:22px"><div class="panel" style="padding:20px"><div class="eyebrow">Current draft</div><h3 style="margin:18px 0 9px">${esc(d.name)}</h3><p class="small muted">${esc(d.retailer)}</p><div class="divider"></div><p class="small muted">${esc(d.order)}<br>${date(d.purchase)}<br>${money(d.price)}</p></div><div class="panel" style="padding:20px"><div class="eyebrow">Existing sample record</div><h3 style="margin:18px 0 9px">Wireless Headphones</h3><p class="small muted">Sample retailer A</p><div class="divider"></div><p class="small muted">RP-1042<br>Sep 15, 2026<br>$59.99</p></div></div><div class="form-actions"><button class="btn secondary" data-action="duplicate-separate">Keep both</button><button class="btn" data-action="duplicate-merge">Merge details ${icon('merge')}</button></div></section><section class="panel"><h2>One order, one clear record.</h2><p class="small muted" style="margin-top:18px">Merging helps prevent duplicate return tasks. It keeps your existing purchase and applies the confirmed details from this draft.</p><div class="divider"></div>${notice('No record will be deleted. This is a duplicate-check demonstration.')}</section></div>`}
function policy(){const d=draft();const start=d.delivery||d.purchase;const due=start?new Date(start+'T12:00:00'):null;if(due)due.setDate(due.getDate()+30);const deadline=due?due.toISOString().slice(0,10):null;const n=(Number(d.quantity)||1);return back('review','Review purchase')+heading('A rule. A deadline. A decision.','See the matched policy before saving a return task.')+steps(2)+`<div class="columns"><section class="panel"><div class="panel-heading"><h2>Matched return policy</h2>${pill('Sample policy')}</div><dl class="key-values"><div class="kv"><dt>Retailer</dt><dd>${esc(d.retailer)}</dd></div><div class="kv"><dt>Category</dt><dd>${esc(d.category||'Other')}</dd></div><div class="kv"><dt>Policy version</dt><dd>Demo policy v1.0</dd></div><div class="kv"><dt>Return window</dt><dd>30 days from ${d.delivery?'delivery':'purchase'}</dd></div><div class="kv"><dt>Required action</dt><dd>Start the retailer’s return request</dd></div><div class="kv"><dt>Request by</dt><dd>${date(deadline)}</dd></div><div class="kv"><dt>Estimated refund</dt><dd>${money(d.price*n)}</dd></div></dl><div class="divider"></div>${notice('Demo rule only. A live policy needs an official source, verification date, and eligibility check.','warn')}<div class="divider"></div><h3>Your decision</h3><div class="decision">${[['keep','bookmark','Keep'],['return','return','Return'],['later','clock','Not sure yet']].map(([id,i,s])=>`<button class="${state.decision===id?'active':''}" data-action="decision" data-value="${id}">${icon(i)}${s}</button>`).join('')}</div><div class="form-actions"><button class="btn" data-action="save-task">${state.decision==='return'?'Save return task':'Save purchase'} ${icon('check')}</button></div></section><section class="panel"><div class="panel-heading"><h2>Your purchase</h2>${icon('receipt')}</div><div class="item-review"><span class="iconbox">${icon('headphones')}</span><div><h3>${esc(d.name)}</h3><p>${esc(d.retailer)} · Qty ${n}</p></div><span class="price">${money(d.price*n)}</span></div><dl class="key-values" style="margin-top:24px"><div class="kv"><dt>Purchased</dt><dd>${date(d.purchase)}</dd></div><div class="kv"><dt>Delivered</dt><dd>${date(d.delivery)}</dd></div><div class="kv"><dt>Order</dt><dd>${esc(d.order||'Not provided')}</dd></div></dl><div class="divider"></div>${notice('Saving a task organizes your next step. It does not request a return from the retailer.')}</section></div>`}
function purchases(){const orders=allPurchases().filter(x=>(x.name+' '+x.retailer+' '+x.order).toLowerCase().includes(purchaseQuery.toLowerCase()));return heading('Purchases','All the details, without digging through your inbox.',button('Add purchase','add','','plus'))+`<div class="list-toolbar"><div class="search">${icon('search')}<input id="purchase-search" aria-label="Search purchases" value="${esc(purchaseQuery)}" placeholder="Search items, retailers, or orders"></div><span class="small muted" style="align-self:center">${orders.length} item${orders.length===1?'':'s'}</span></div><section class="panel"><div class="panel-heading"><h2>Your purchase history</h2>${pill('Sample records + your drafts')}</div><div class="purchase-list">${orders.length?orders.map(x=>`<div class="purchase-item"><span class="iconbox">${icon(x.icon||'box')}</span><div class="item-data"><h3>${esc(x.name)}</h3><p>${esc(x.retailer)} · ${esc(x.order||'No order number')}</p><p>Purchased ${date(x.purchase)}</p></div>${pill(x.decision==='keep'?'Keeping':x.decision==='later'?'Decide later':stageNames[itemStage(x)])}<span class="purchase-price">${money(x.price*(x.quantity||1))}</span>${x.decision&&x.decision!=='return'?`<button class="row-arrow" data-action="make-return" data-value="${x.id}" aria-label="Create return for ${esc(x.name)}">${icon('return')}</button>`:`<a class="row-arrow" href="#detail" data-item="${x.id}" aria-label="View ${esc(x.name)}">${icon('arrow')}</a>`}</div>`).join(''):`<div class="empty">${icon('search')}No purchases match “${esc(purchaseQuery)}”.</div>`}</div><div class="inline-note">${icon('info')}Importing a purchase does not automatically start a return.</div></section>`}
function tasks(){const all=allTasks();const list=all.filter(x=>taskFilter==='all'||(taskFilter==='active'?itemStage(x)<4:itemStage(x)===4));return heading('Returns','A manageable list. One next step at a time.',button('Add purchase','add','','plus'))+`<div class="tabs">${[['active','Active'],['complete','Completed'],['all','All tasks']].map(([id,s])=>`<button class="tab ${taskFilter===id?'active':''}" data-action="task-filter" data-value="${id}">${s} ${id==='all'?all.length:all.filter(x=>id==='active'?itemStage(x)<4:itemStage(x)===4).length}</button>`).join('')}</div><section class="panel" style="padding-top:8px;padding-bottom:8px">${list.length?list.map(x=>`<div class="task-list-card"><span class="iconbox">${icon(x.icon||'box')}</span><div class="item-data"><h3>${esc(x.name)}</h3><p>${esc(x.retailer)} · ${esc(x.order||'No order number')}</p><div class="task-facts"><span>${x.deadline?'Request by '+date(x.deadline):'Date needs confirmation'}</span><span>Qty ${x.quantity||1}</span></div></div><div class="right"><span>${pill(stageNames[itemStage(x)],x.id==='headphones'&&itemStage(x)<1?'urgent':'')}</span><strong>${money(x.price*(x.quantity||1))}</strong><a class="row-arrow" href="#detail" data-item="${x.id}" aria-label="Open ${esc(x.name)} return">${icon('arrow')}</a></div></div>`).join(''):`<div class="empty">${icon('check')}No ${taskFilter==='complete'?'completed':'active'} returns here yet.</div>`}</section>`}
function detail(){const x=focusItem(),s=itemStage(x);return back('tasks','All return tasks')+heading(esc(x.name),'Keep the next step clear. Follow through until the refund lands.',`<button class="btn secondary" data-action="edit-task">${icon('edit')}Edit task</button>`)+`<div class="columns"><div class="stack"><section class="panel"><div class="panel-heading"><div style="display:flex;gap:15px;align-items:center"><span class="iconbox">${icon(x.icon||'box')}</span><div><h2>${esc(x.name)}</h2><p class="small muted">${esc(x.retailer)} · ${esc(x.order||'No order number')}</p></div></div>${pill(stageNames[s])}</div><dl class="key-values"><div class="kv"><dt>Return quantity</dt><dd>${x.quantity||1} item${(x.quantity||1)>1?'s':''}</dd></div><div class="kv"><dt>Policy version</dt><dd>Demo policy v1.0</dd></div><div class="kv"><dt>Request deadline</dt><dd>${date(x.deadline)}</dd></div><div class="kv"><dt>Review blockers</dt><dd>${x.delivery?'None in the sample record':'Delivery date not confirmed'}</dd></div><div class="kv"><dt>Estimated refund</dt><dd>${money(x.price*(x.quantity||1))}<br><small class="muted">Original payment method</small></dd></div></dl><div class="divider"></div><h3>Next action</h3><p class="small muted" style="margin:10px 0 20px">${s===0?'Open the retailer’s return flow and confirm the available methods.':s===1?'Prepare the package and take it to the eligible drop-off location.':s<4?'Keep your receipt and watch for the retailer’s refund confirmation.':'The refund is marked received. This task is complete.'}</p>${s===0?'<button class="btn full" data-action="retailer">'+icon('external')+'Open retailer return flow</button>':button(s===4?'View completed return':'View return progress','tracking','full')}<div class="inline-note">${icon('info')}Opening a link does not mark a return as initiated.</div></section><section class="panel"><div class="panel-heading"><h2>Method & materials</h2><button class="link" data-action="method">Change ${icon('edit')}</button></div><dl class="key-values"><div class="kv"><dt>Return method</dt><dd>${esc(x.method||'Carrier drop-off')}</dd></div><div class="kv"><dt>Sample location</dt><dd>Parcel Point · Downtown<br>128 Market Street</dd></div><div class="kv"><dt>Shipping fee</dt><dd>$0.00 in the demo</dd></div><div class="kv"><dt>What to bring</dt><dd>Packaged item + matching label</dd></div></dl><div class="divider"></div>${notice('Label and QR code must come from the retailer. This demo does not generate a valid return label.')}</section></div><div class="stack"><section class="panel"><h2>Ready for the next step?</h2><div class="checklist" style="margin:23px 0">${['Pack each return separately','Check the matching label','Save your drop-off receipt'].map((label,i)=>`<label class="check-row"><input type="checkbox" data-check="${x.id}-${i}" ${state.checks?.[x.id+'-'+i]?'checked':''}><span>${label}</span></label>`).join('')}</div><button class="btn full" data-action="advance">${s===0?'Demo: mark return requested':s===1?'Mark as dropped off':s===2?'Mark retailer received':s===3?'Confirm refund received':'View completion'} ${icon('arrow')}</button><div class="file-note">Updated by you · Changes stay in this browser</div></section><section class="panel"><div class="panel-heading"><h2>Return progress</h2><a class="link" href="#tracking">Details ${icon('arrow')}</a></div>${timeline(x)}</section></div></div>`}
function timeline(x){const s=itemStage(x);return `<div class="timeline">${['Return requested','Ready to drop off','Dropped off','Retailer received','Refund received'].map((label,i)=>`<div class="timeline-step ${i<s?'done':i===s?'current':''}"><span class="timeline-dot"></span><div><h3>${label}</h3><small>${i===s?(s===0?'Awaiting your confirmation':'Current step'):i<s?'Marked by you':'Not yet confirmed'}</small></div>${i===s?pill('Current'):''}</div>`).join('')}</div>`}
function tracking(){const x=focusItem(),s=itemStage(x);const history=state.history.filter(h=>h.item===x.id);return back('detail','Task details')+heading('Follow the money back.','Keep the evidence. Confirm each step. Close when refunded.')+`<div class="columns equal"><section class="panel"><div class="panel-heading"><h2>Progress tracking</h2>${pill('Updated by you')}</div><div class="item-review"><span class="iconbox">${icon(x.icon||'box')}</span><div><h3>${esc(x.name)}</h3><p>${esc(x.retailer)}</p></div><span class="price">${money(x.price*(x.quantity||1))}</span></div>${timeline(x)}<button class="btn full" data-action="advance">${s<4?['Mark return requested','Mark as dropped off','Mark retailer received','Confirm refund received'][s]:'Completed'} ${icon('check')}</button></section><div class="stack"><section class="panel"><div class="panel-heading"><h2>Recent history</h2>${icon('clock')}</div>${history.length?history.slice().reverse().map(h=>`<div class="task-row"><span class="iconbox">${icon('check')}</span><div class="task-copy"><h3>${esc(h.label)}</h3><p>${esc(h.time)} · User update</p></div></div>`).join(''):`<div class="empty" style="padding:30px 10px">No new updates yet.<br><small>Mark a step to start the history.</small></div>`}</section><section class="panel"><h2>Refund status</h2><div class="metric-value" style="margin-top:22px">${money(x.price*(x.quantity||1))}</div><p class="small muted">${s===4?'Marked received by you.':'Estimated refund · Original payment method'}</p><div class="divider"></div>${notice('User updates are not retailer verification. The actual refund and timing come from the retailer.')}</section></div></div>`}
function plan(){return heading('A plan you can actually do.','Protect the deadline. Group eligible returns into fewer stops.',`<button class="btn secondary" data-action="save-plan">${icon('bookmark')}${state.planSaved?'Plan saved':'Save plan'}</button>`)+`<section class="panel" style="margin-bottom:24px"><form id="plan-form" class="form-grid plan-controls"><label class="field">Starting point<input name="location" value="${esc(state.planLocation||'Downtown')}" required></label><label class="field">Available day<input name="day" type="date" value="${esc(state.planDay||'2026-10-14')}" min="2026-10-13" max="2026-10-15" required></label><label class="field">Your priority<select name="priority"><option ${state.planPriority==='Meet deadlines'?'selected':''}>Meet deadlines</option><option ${state.planPriority==='Fewer stops'?'selected':''}>Fewer stops</option><option ${state.planPriority==='Lower fees'?'selected':''}>Lower fees</option></select></label><div style="grid-column:1/-1;display:flex;align-items:center;justify-content:space-between"><small class="muted">Plan uses sample locations and eligible methods.</small><button class="btn secondary" type="submit">Update plan ${icon('arrow')}</button></div></form></section><div class="columns"><div class="stack"><section class="panel"><div class="panel-heading"><h2>Before you leave</h2>${pill('About 10 minutes')}</div><div class="checklist">${['Request the headphones return in the retailer’s flow','Pack the headphones, hoodie, and phone case separately','Print each label or save the retailer’s return code'].map((label,i)=>`<label class="check-row"><input type="checkbox" data-check="plan-${i}" ${state.checks?.['plan-'+i]?'checked':''}><span>${label}</span></label>`).join('')}</div></section><section class="panel"><div class="stop"><span class="stop-number">01</span><div class="stop-content"><div style="display:flex;justify-content:space-between;gap:10px"><h3>Parcel Point · Downtown</h3><span class="stop-time">2:10 PM</span></div><p>Sample location · 128 Market Street</p><div class="stop-items">${icon('shirt')} Hoodie + phone case · Two separate packages</div></div></div><div class="divider"></div><div class="stop"><span class="stop-number">02</span><div class="stop-content"><div style="display:flex;justify-content:space-between;gap:10px"><h3>Parcel Point · City Center</h3><span class="stop-time">2:35 PM</span></div><p>Sample location · 18 Center Avenue</p><div class="stop-items">${icon('headphones')} Headphones · Package and matching label</div></div></div></section></div><div class="stack"><section class="panel"><div class="eyebrow">Plan summary</div><h2 style="margin:20px 0 9px">${date(state.planDay||'2026-10-14')}</h2><p class="small muted">2–3 PM · Starting from ${esc(state.planLocation||'Downtown')}</p><div class="divider"></div><dl class="key-values"><div class="kv"><dt>Returns</dt><dd>3 items</dd></div><div class="kv"><dt>Drop-off locations</dt><dd>2 stops</dd></div><div class="kv"><dt>Potential refund</dt><dd>$128.99</dd></div><div class="kv"><dt>Earliest request deadline</dt><dd>October 15</dd></div></dl><div class="divider"></div><h3>Why this order?</h3><p class="small muted" style="margin-top:10px">The headphones deadline comes first. The other two sample returns share an eligible drop-off point.</p></section>${notice('Confirm opening hours and eligibility before leaving. This is a sample plan, with no live route optimization.')}</div></div>`}
function settings(){return heading('Your workspace, your way.','Choose what to remember, and how to be reminded.',`<a class="btn secondary" href="#login">${icon('shield')}View sign-in screen</a>`)+`<form id="settings-form"><div class="columns equal"><section class="panel"><div class="panel-heading"><h2>Account</h2>${icon('settings')}</div><div class="form-grid">${field('Name','name',state.name,'text','required maxlength="60"')}${field('Email','email',state.email,'email','required')}<label class="field full">Time zone<select name="timezone">${[['America/New_York','Eastern Time — New York'],['America/Los_Angeles','Pacific Time — Los Angeles'],['Europe/London','London']].map(([v,s])=>`<option value="${v}" ${state.timezone===v?'selected':''}>${s}</option>`).join('')}</select></label></div><div class="divider"></div><h3>Forwarding address</h3><p class="small muted" style="margin:9px 0 14px">A dedicated inbox for order confirmations.</p><div class="code-box"><span>alex@inbox.returnpilot.example</span><button type="button" class="icon-button" data-action="copy" aria-label="Copy example forwarding address">${icon('copy')}</button></div><div class="file-note">Example address. Email receiving is not connected.</div></section><section class="panel"><div class="panel-heading"><h2>Reminder preferences</h2>${icon('bell')}</div><div class="setting-group" style="padding-top:0"><h3>Before the return deadline</h3><div class="checklist" style="margin-top:16px">${[7,3,1].map(n=>`<label class="check-row"><input type="checkbox" name="lead" value="${n}" ${state.lead.includes(n)?'checked':''}><span>${n} day${n===1?'':'s'} before</span></label>`).join('')}</div></div><div class="setting-group"><h3>Reminder channels</h3><div class="checklist" style="margin-top:16px"><label class="check-row"><input type="checkbox" name="emailChannel" ${state.channels.email?'checked':''}><span>Email reminders</span></label><label class="check-row"><input type="checkbox" name="appChannel" ${state.channels.app?'checked':''}><span>In-app notifications</span></label></div></div><div class="setting-group settings-row"><div><h3>Pause all reminders</h3><p>Take a break from notifications.</p></div><input aria-label="Pause all reminders" type="checkbox" class="switch" name="pause" ${!state.notify?'checked':''}></div><div class="inline-note">${icon('info')}Preferences save locally. No reminders are sent in this demo.</div></section></div><div class="form-actions"><span class="small"><button type="button" class="link" data-action="reset-demo">Reset demo workspace</button></span><button class="btn" type="submit">Save settings ${icon('check')}</button></div></form>`}
const views={today,login,setup,add,upload,manual,review,duplicate,policy,purchases,tasks,detail,tracking,plan,settings};
function render(){const route=location.hash.slice(1)||'today';const fn=views[route]||views.today;document.getElementById('app').innerHTML=route==='login'?login():shell(route,fn());document.title=`${route==='login'?'Welcome':route==='setup'?'Account setup':labels[route]||'Today'} — Return Pilot`;window.scrollTo(0,0)}
window.addEventListener('hashchange',render);
function toast(s){const el=document.getElementById('toast');el.textContent=s;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3200)}
function modal(title,body){const d=document.getElementById('modal');d.innerHTML=`<button class="icon-button modal-close" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button><h2>${title}</h2>${body}`;d.showModal()}
function updateDraft(form){const f=new FormData(form);state.draft={...draft(),...Object.fromEntries(f),price:Number(f.get('price')),quantity:Number(f.get('quantity')||1)};persist()}
document.addEventListener('click',async e=>{
 const item=e.target.closest('[data-item]');if(item){state.selectedItem=item.dataset.item;persist()}
 const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;
 if(action==='reminders')location.hash='settings';
 if(action==='close-modal')document.getElementById('modal').close();
 if(action==='copy'){try{await navigator.clipboard.writeText('alex@inbox.returnpilot.example');toast('Example forwarding address copied.')}catch{toast('Example address: alex@inbox.returnpilot.example')}}
 if(action==='reset-demo')modal('Reset demo workspace',`<p>This restores the sample orders and clears edits, progress, and settings saved by this demo in this browser.</p><button class="btn full" data-action="confirm-reset">Restore sample data</button>`);
 if(action==='confirm-reset'){state={name:'Alex',email:'alex@example.com',timezone:'America/New_York',notify:true,lead:[7,3,1],channels:{email:true,app:true},taskState:1,history:[],decision:'return',draft:null,tasksAdded:[],planSaved:false};persist();document.getElementById('modal').close();location.hash='today';render();toast('Sample workspace restored.')}
 if(action==='google')modal('Google sign-in',`<p>Google authentication is not connected in this prototype. You can explore the complete flow using the demo workspace.</p>${button('Explore the demo','setup','full')}`);
 if(action==='email')modal('Forward your order email',`<p>Forwarding is one of the four purchase inputs in the reference flow.</p><div class="code-box">alex@inbox.returnpilot.example<button class="icon-button" data-action="copy" aria-label="Copy example address">${icon('copy')}</button></div><p style="margin-top:16px">This is an example address. It cannot receive mail.</p>${button('Try a sample instead','upload','full')}`);
 if(action==='sample'){state.draft={retailer:'Sample retailer A',name:'Wireless Headphones',price:59.99,purchase:'2026-09-15',delivery:'2026-09-15',order:'RP-1042',category:'Electronics',source:'Sample receipt',quantity:1};fileURL=null;fileName='';persist();location.hash='review'}
 if(action==='duplicate-merge'){state.draft={...draft(),merge:true};persist();toast('Draft details will update the sample purchase.');location.hash='policy'}
 if(action==='duplicate-separate'){state.draft={...draft(),merge:false};persist();location.hash='policy'}
 if(action==='decision'){state.decision=el.dataset.value;persist();render()}
 if(action==='make-return'){const id=el.dataset.value;state.purchaseOverrides={...(state.purchaseOverrides||{}),[id]:{...(state.purchaseOverrides?.[id]||{}),decision:'return'}};state.selectedItem=id;persist();location.hash='detail';toast('Purchase added to your return list.')}
 if(action==='review-hoodie'){state.draft={...sampleOrders[1],source:'Sample record',quantity:1,delivery:''};persist();location.hash='review'}
 if(action==='save-task'){
  const d=draft();let deadline=null;if(d.delivery||d.purchase){const due=new Date((d.delivery||d.purchase)+'T12:00:00');due.setDate(due.getDate()+30);deadline=due.toISOString().slice(0,10)}
  let id;
  if(d.merge){id='headphones';state.purchaseOverrides={...(state.purchaseOverrides||{}),headphones:{...d,deadline,decision:state.decision}}}
  else{id='draft-'+Date.now();state.tasksAdded.push({...d,id,deadline,icon:d.category==='Apparel'?'shirt':d.category==='Electronics'?'headphones':'box',stage:0,decision:state.decision})}
  state.selectedItem=id;persist();toast(state.decision==='return'?'Return task saved in this browser.':'Purchase saved in this browser.');location.hash=state.decision==='return'?'tasks':'purchases';
 }
 if(action==='task-filter'){taskFilter=el.dataset.value;render()}
 if(action==='advance'){
  const x=focusItem(),s=itemStage(x);if(s>=4){toast('This return is already marked complete.');return}
  if(s===3){modal('Confirm refund received',`<p>Confirm that ${money(x.price*(x.quantity||1))} has arrived in your account before closing this task.</p><button class="btn full" data-action="confirm-refund">Refund received ${icon('check')}</button>`);return}
  advance(x,s+1);
 }
 if(action==='confirm-refund'){advance(focusItem(),4);document.getElementById('modal').close()}
 if(action==='retailer')modal('Continue with your retailer',`<p>A live task would open the official return portal for this order. Sample retailers do not have a connected portal.</p><p>After submitting your request, mark it here so you can follow the next step.</p><button class="btn full" data-action="requested">Demo: mark return requested ${icon('arrow')}</button>`);
 if(action==='requested'){advance(focusItem(),1);document.getElementById('modal').close()}
 if(action==='edit-task'){
  const x=focusItem();modal('Edit return task',`<form id="edit-task-form"><div class="form-grid">${field('Item name','name',x.name,'text','required maxlength="150"')}${field('Return quantity','quantity',x.quantity||1,'number','required min="1" max="99"')}${field('Delivery date','delivery',x.delivery,'date','max="2026-10-13"')}${field('Request deadline','deadline',x.deadline,'date')}</div><div class="form-actions"><button type="button" class="link danger-link" data-action="delete-task">Remove task</button><button class="btn" type="submit">Save changes ${icon('check')}</button></div></form>`)
 }
 if(action==='delete-task'){state.hiddenItemIds=[...(state.hiddenItemIds||[]),focusItem().id];persist();document.getElementById('modal').close();location.hash='tasks';toast('Task removed from this demo workspace.')}
 if(action==='method')modal('Choose a return method',`<p>These options demonstrate the method selector. Actual eligibility and fees depend on the retailer.</p><div class="stack">${['Carrier drop-off','In-store return','Scheduled pickup'].map(s=>`<button class="btn secondary full" data-action="choose-method" data-value="${s}">${s}</button>`).join('')}</div>`);
 if(action==='choose-method'){state.purchaseOverrides={...(state.purchaseOverrides||{}),[focusItem().id]:{...(state.purchaseOverrides?.[focusItem().id]||{}),method:el.dataset.value}};persist();document.getElementById('modal').close();render();toast('Sample return method updated.')}
 if(action==='save-plan'){state.planSaved=!state.planSaved;persist();render();toast(state.planSaved?'Plan saved in this browser.':'Plan removed from saved items.')}
});
function advance(x,next){state.stages={...(state.stages||{}),[x.id]:next};state.history.push({item:x.id,label:stageNames[next],time:'Demo session · Oct 13, 2026'});persist();render();toast(next===4?'Refund marked received. Task completed.':'Progress updated in this browser.')}
document.addEventListener('submit',e=>{
 const form=e.target;if(!form.id)return;e.preventDefault();const f=new FormData(form);
 if(form.id==='login-form'){state.email=f.get('email');persist();location.hash='setup'}
 if(form.id==='setup-form'){state.name=f.get('name');state.email=f.get('email');state.timezone=f.get('timezone');persist();location.hash='today';toast('Your demo workspace is ready.')}
 if(form.id==='manual-form'||form.id==='review-form'){
  if(f.get('delivery')&&f.get('purchase')&&f.get('delivery')<f.get('purchase')){toast('Delivery cannot be before purchase. Please check the dates.');return}
  updateDraft(form);if(form.id==='manual-form'){state.draft.merge=false;state.draft.source='Manual entry';persist();location.hash='review'}else location.hash=state.draft.order==='RP-1042'?'duplicate':'policy';
 }
 if(form.id==='settings-form'){state.name=f.get('name');state.email=f.get('email');state.timezone=f.get('timezone');state.lead=f.getAll('lead').map(Number);state.notify=!f.has('pause');state.channels={email:f.has('emailChannel'),app:f.has('appChannel')};persist();render();toast('Preferences saved. No notifications are sent in this demo.')}
 if(form.id==='plan-form'){state.planLocation=f.get('location');state.planDay=f.get('day');state.planPriority=f.get('priority');persist();render();toast('Plan preferences updated. Sample stops are unchanged.')}
 if(form.id==='edit-task-form'){const x=focusItem();state.purchaseOverrides={...(state.purchaseOverrides||{}),[x.id]:{...(state.purchaseOverrides?.[x.id]||{}),...Object.fromEntries(f),quantity:Number(f.get('quantity'))}};persist();document.getElementById('modal').close();render();toast('Task details updated.')}
});
document.addEventListener('change',e=>{if(e.target.id==='receipt-file')acceptFile(e.target.files[0]);if(e.target.dataset.check){state.checks={...(state.checks||{}),[e.target.dataset.check]:e.target.checked};persist()}});
document.addEventListener('input',e=>{if(e.target.id==='purchase-search'){const start=e.target.selectionStart;purchaseQuery=e.target.value;render();const input=document.getElementById('purchase-search');input.focus();input.setSelectionRange(start,start)}});
function acceptFile(f){if(!f)return;if(f.size>10*1024*1024){toast('Please choose a file smaller than 10 MB.');return}if(!['image/jpeg','image/png','application/pdf'].includes(f.type)){toast('Choose a JPG, PNG, or PDF receipt.');return}if(fileURL)URL.revokeObjectURL(fileURL);selectedFile=f;fileName=f.name;fileURL=f.type.startsWith('image/')?URL.createObjectURL(f):null;state.draft={retailer:'',name:'',price:'',purchase:'',delivery:'',order:'',category:'Other',source:'Uploaded file',quantity:1};persist();render();toast('File selected locally. Enter or review the purchase details.')}
document.addEventListener('dragover',e=>{const zone=e.target.closest('#drop-zone');if(zone){e.preventDefault();zone.classList.add('dragging')}});
document.addEventListener('dragleave',e=>e.target.closest('#drop-zone')?.classList.remove('dragging'));
document.addEventListener('drop',e=>{if(e.target.closest('#drop-zone')){e.preventDefault();acceptFile(e.dataTransfer.files[0])}});
window.addEventListener('hashchange',()=>{const d=document.getElementById('modal');if(d.open)d.close()});
render();
